shared_html.shared_css:
/* ============ Shared header ============ */
.site-nav{
  position:relative;
  background:var(--surface);
  color:var(--text);
  border-bottom:1px solid color-mix(in srgb, var(--ornament) 40%, transparent);
  background-image:url("svg/quatrefoil-in-square.svg");
  background-size:80px 80px;
  background-repeat:repeat;
  background-blend-mode:multiply;
}
.site-nav__arcade{
  height:14px;
  background:
    linear-gradient(var(--secondary),var(--secondary)) center/100% 2px no-repeat,
    repeating-linear-gradient(90deg,
      var(--primary) 0 2px,
      transparent 2px 28px);
  border-bottom:1px solid var(--primary);
}
.site-nav__inner{
  display:grid;
  grid-template-columns:auto 1fr;
  gap:2.5rem;
  align-items:center;
  max-width:1240px;
  margin:0 auto;
  padding:1.75rem 2rem 1.25rem;
}
.site-nav__brand{
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  text-decoration:none;
  color:var(--text-emphasis);
  line-height:1;
}
.site-nav__kicker{
  font-family:"Crimson Pro",serif;
  font-style:italic;
  font-size:.7rem;
  letter-spacing:.32em;
  text-transform:uppercase;
  color:color-mix(in srgb,var(--text) 70%,transparent);
  margin-bottom:.55rem;
}
.site-nav__wordmark{
  font-family:"Cinzel Decorative",serif;
  font-weight:900;
  font-size:1.85rem;
  letter-spacing:.06em;
  color:var(--primary);
  text-shadow:0 0 1px var(--surface);
}
.site-nav__subtitle{
  font-family:"Crimson Pro",serif;
  font-style:italic;
  font-size:.95rem;
  letter-spacing:.18em;
  color:var(--text);
  margin-top:.35rem;
}
.site-nav__menu{ justify-self:end; }
.site-nav__list{
  list-style:none;
  display:flex;
  flex-wrap:wrap;
  gap:.25rem;
  margin:0;
  padding:0;
}
.site-nav__item{ position:relative; }
.site-nav__item + .site-nav__item::before{
  content:"✦";
  color:var(--ornament);
  opacity:.55;
  font-size:.7rem;
  align-self:center;
  padding:0 .35rem;
}
.site-nav__list{ align-items:center; }
.site-nav__link{
  font-family:"Cinzel Decorative",serif;
  font-weight:700;
  font-size:.82rem;
  letter-spacing:.18em;
  text-transform:uppercase;
  color:var(--text);
  text-decoration:none;
  padding:.6rem .9rem;
  border-top:1px solid transparent;
  border-bottom:1px solid transparent;
  transition:color .2s, border-color .2s, background .2s;
}
.site-nav__link:hover,
.site-nav__link:focus{
  color:var(--primary);
  border-top-color:var(--primary);
  border-bottom-color:var(--primary);
  background:color-mix(in srgb,var(--bg) 60%, transparent);
}
.site-nav__cusp{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:1rem;
  padding:.55rem 1rem .8rem;
  background:var(--bg);
  border-top:1px solid color-mix(in srgb,var(--ornament) 50%, transparent);
}
.site-nav__cusp img{
  width:18px;height:18px;
  filter:invert(72%) sepia(38%) saturate(548%) hue-rotate(7deg) brightness(92%) contrast(92%);
}
.site-nav__motto{
  font-family:"Cinzel Decorative",serif;
  font-style:normal;
  letter-spacing:.4em;
  text-transform:uppercase;
  font-size:.72rem;
  color:var(--primary);
}

/* ============ Shared footer ============ */
.site-footer{
  position:relative;
  margin-top:6rem;
  background:var(--surface);
  color:var(--text);
  border-top:1px solid var(--primary);
}
.site-footer__arcade{
  height:48px;
  background-image:
    repeating-linear-gradient(90deg,
      transparent 0 8px,
      var(--primary) 8px 9px,
      transparent 9px 64px),
    radial-gradient(circle at 32px 48px,
      var(--bg) 0 22px,
      var(--primary) 22px 23px,
      transparent 23px);
  background-size:64px 100%, 64px 100%;
  background-repeat:repeat-x;
  border-bottom:1px solid color-mix(in srgb, var(--primary) 50%, transparent);
}
.site-footer__inner{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:2.5rem;
  max-width:1240px;
  margin:0 auto;
  padding:3rem 2rem 2rem;
}
.site-footer__col{
  display:flex;
  flex-direction:column;
  gap:.75rem;
}
.site-footer__col--seal{ align-items:flex-start; }
.site-footer__seal{
  width:64px;height:64px;
  filter:invert(72%) sepia(38%) saturate(548%) hue-rotate(7deg) brightness(92%) contrast(92%);
  margin-bottom:.5rem;
}
.site-footer__name{
  font-family:"Cinzel Decorative",serif;
  font-weight:700;
  font-size:1.05rem;
  letter-spacing:.08em;
  color:var(--primary);
  margin:0;
  line-height:1.35;
}
.site-footer__founded{
  font-family:"Crimson Pro",serif;
  font-style:italic;
  font-size:.9rem;
  margin:0;
  color:color-mix(in srgb,var(--text) 75%, transparent);
}
.site-footer__heading{
  font-family:"Cinzel Decorative",serif;
  font-size:.78rem;
  letter-spacing:.32em;
  text-transform:uppercase;
  color:var(--primary);
  margin:0 0 .25rem;
  padding-bottom:.5rem;
  border-bottom:1px solid color-mix(in srgb,var(--primary) 40%,transparent);
}
.site-footer__address,
.site-footer__hours{
  font-family:"Crimson Pro",serif;
  font-size:.95rem;
  font-style:normal;
  line-height:1.65;
  margin:0;
  color:var(--text);
}
.site-footer__hours em{
  color:color-mix(in srgb,var(--secondary) 80%, var(--text));
  font-family:"Crimson Pro",serif;
}
.site-footer__nav{
  list-style:none;
  margin:0;padding:0;
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:.35rem .75rem;
}
.site-footer__nav a{
  font-family:"Crimson Pro",serif;
  font-size:.95rem;
  color:var(--text);
  text-decoration:none;
  border-bottom:1px solid transparent;
  transition:color .2s, border-color .2s;
}
.site-footer__nav a:hover{
  color:var(--primary);
  border-bottom-color:var(--primary);
}
.site-footer__band{
  height:18px;
  background:repeating-linear-gradient(90deg,
    var(--secondary) 0 28px,
    var(--bg) 28px 56px,
    var(--accent) 56px 84px,
    var(--bg) 84px 112px,
    var(--primary) 112px 116px,
    var(--bg) 116px 144px);
  border-top:1px solid var(--primary);
  border-bottom:1px solid var(--primary);
}
.site-footer__colophon{
  text-align:center;
  font-family:"Crimson Pro",serif;
  font-style:italic;
  font-size:.82rem;
  letter-spacing:.14em;
  color:color-mix(in srgb,var(--text) 65%,transparent);
  margin:0;
  padding:1.2rem 1rem 1.6rem;
  background:var(--surface);
}
.site-footer__colophon span[lang="la"]{
  color:var(--primary);
  font-style:normal;
  letter-spacing:.28em;
  text-transform:uppercase;
  font-size:.74rem;
}

/* ============ Responsive ============ */
@media (max-width: 880px){
  .site-nav__inner{
    grid-template-columns:1fr;
    gap:1.25rem;
    text-align:center;
  }
  .site-nav__brand{ align-items:center; }
  .site-nav__menu{ justify-self:center; }
  .site-nav__list{ justify-content:center; }
  .site-footer__inner{
    grid-template-columns:1fr 1fr;
    gap:2rem;
  }
}
@media (max-width: 520px){
  .site-footer__inner{ grid-template-columns:1fr; }
  .site-nav__item + .site-nav__item::before{ display:none; }
}
